import {
  ADJUSTMENT_PATH_CONTEXT_PREFIX,
  PATH_CONTEXTS,
  lowerConfidence,
  type Finding,
  type PathContext,
} from "./finding.js";

/*
 * Path context
 * ------------
 * Findings in test code, documentation, examples, vendored and generated files
 * are rarely about the shipped product, so their confidence is lowered. The
 * classification is made from file paths, which the audited repository
 * controls: naming a file `test_x.py` is free. The policy that follows:
 *
 * 1. A finding is never dropped, only lowered, and it says so itself
 *    (`pathContext`, `confidenceOriginal`, `adjustments`).
 * 2. Only the PATH lowers confidence. A "generated" header comment
 *    (`# @generated`, `DO NOT EDIT`) is recorded as `pathContext: generated`
 *    but changes nothing: one comment line must not take a whole file out of
 *    the exit code. Well-known generated and vendored paths (`node_modules/`,
 *    `vendor/`, `*.min.js`, `*_pb2.py`, `*.pb.go`) do lower.
 * 3. Findings that are just as dangerous wherever the file sits keep their
 *    confidence: critical findings reported with high confidence, private-key
 *    blocks, credentials embedded in a URL, credentials in a provider format,
 *    and everything in CI / workflow files, Dockerfiles, dependency manifests
 *    and agent instruction files. See `pathContextExemption`.
 * 4. Every finding at or above `--fail-on` that leaves the exit-code set this
 *    way is counted in a WARNING on the report cover and in the terminal and
 *    CI summaries (`summary.reductions`), and `--include-tests` (or
 *    `--untrusted`) turns the lowering off.
 */

const TEST_DIRS = new Set([
  "test",
  "tests",
  "__tests__",
  "spec",
  "testing",
  "testdata",
  "fixtures",
  // Rust: Criterion benchmarks and cargo-fuzz targets.
  "benches",
  "fuzz",
]);
const DOCS_DIRS = new Set(["docs", "doc"]);
const EXAMPLE_DIRS = new Set(["examples", "example", "samples", "demo", "tutorial"]);
const VENDORED_DIRS = new Set(["vendor", "third_party", "node_modules", "bower_components"]);
const GENERATED_DIRS = new Set(["dist", "build"]);

const TEST_FILE =
  /^(?:test_.*\.py|.*_test\.(?:go|py|rs)|tests\.rs|conftest\.py|.*\.(?:test|spec)\.(?:[cm]?[jt]sx?))$/;
const DOCS_FILE = /\.(?:md|rst|adoc)$/;
const GENERATED_FILE = /(?:\.min\.(?:js|css)|_pb2(?:_grpc)?\.pyi?|\.pb\.go)$/;

function segmentsOf(relPath: string): { dirs: string[]; base: string } {
  const parts = relPath
    .split("\\")
    .join("/")
    .split("/")
    .filter((part) => part.length > 0 && part !== ".")
    .map((part) => part.toLowerCase());
  const base = parts.pop() ?? "";
  return { dirs: parts, base };
}

/**
 * Classify a root-relative path by its directory names and file name.
 *
 * When several classes apply the strongest effect wins: vendored, generated
 * (both make a finding low confidence), then test, example, docs (one step
 * down). Names are compared case-insensitively. Returns undefined for
 * ordinary source.
 */
export function classifyPath(relPath: string): PathContext | undefined {
  const { dirs, base } = segmentsOf(relPath);
  const inDir = (names: Set<string>): boolean => dirs.some((dir) => names.has(dir));
  if (inDir(VENDORED_DIRS)) return "vendored";
  if (inDir(GENERATED_DIRS) || GENERATED_FILE.test(base)) return "generated";
  if (inDir(TEST_DIRS) || TEST_FILE.test(base)) return "test";
  if (inDir(EXAMPLE_DIRS)) return "example";
  if (inDir(DOCS_DIRS) || DOCS_FILE.test(base)) return "docs";
  return undefined;
}

/** How many leading lines are searched for a "generated" header. */
export const GENERATED_HEADER_LINES = 5;

const GENERATED_HEADER =
  /^\s*(?:#|\/\/|\/\*+|\*|--|;|<!--|"""|''')\s*.{0,200}?(?:\bgenerated by\b|\bdo not edit\b|@generated\b)/i;

/**
 * True when one of the first `GENERATED_HEADER_LINES` lines is a comment that
 * says the file is generated ("Code generated by protoc-gen-go. DO NOT EDIT.",
 * "# Generated by Django", "@generated"). Only comment lines count, so prose
 * that mentions a generator does not match.
 */
export function hasGeneratedHeader(text: string): boolean {
  let start = 0;
  for (let line = 0; line < GENERATED_HEADER_LINES && start <= text.length; line += 1) {
    let end = text.indexOf("\n", start);
    if (end < 0) end = text.length;
    // A header is short; an over-long first line is minified code or data.
    if (end - start <= 400 && GENERATED_HEADER.test(text.slice(start, end))) return true;
    start = end + 1;
  }
  return false;
}

/** What a path context was decided from. Only `path` lowers confidence. */
export type PathContextSource = "path" | "header";

export interface FileClassification {
  context?: PathContext;
  source?: PathContextSource;
}

/**
 * Path context of a file and what decided it. The path classification wins
 * whenever there is one; `generated` with source `header` is returned only
 * when the path says nothing and the text starts with a generated-file
 * header. Markdown and other prose is never classified by its content.
 */
export function classifyFileDetailed(
  relPath: string,
  text: string | undefined,
  language: string,
): FileClassification {
  const byPath = classifyPath(relPath);
  if (byPath) return { context: byPath, source: "path" };
  if (
    text !== undefined &&
    language !== "unknown" &&
    language !== "markdown" &&
    hasGeneratedHeader(text)
  ) {
    return { context: "generated", source: "header" };
  }
  return {};
}

/** Path context of a file; see `classifyFileDetailed`. */
export function classifyFile(
  relPath: string,
  text: string | undefined,
  language: string,
): PathContext | undefined {
  return classifyFileDetailed(relPath, text, language).context;
}

const CI_FILE =
  /(?:^|\/)(?:\.github\/(?:workflows|actions)\/.+|action\.ya?ml|\.gitlab-ci\.ya?ml|\.gitlab\/ci\/.+|\.circleci\/.+|\.travis\.ya?ml|azure-pipelines[^/]*\.ya?ml|bitbucket-pipelines\.ya?ml|\.drone\.ya?ml|\.buildkite\/.+|jenkinsfile[^/]*|\.woodpecker(?:\.ya?ml|\/.+)|appveyor\.ya?ml|cloudbuild[^/]*\.ya?ml|\.tekton\/.+)$/i;

/** CI and workflow definitions: they run with the project's credentials. */
export function isCiFile(relPath: string): boolean {
  return CI_FILE.test(relPath.split("\\").join("/"));
}

const DOCKERFILE = /(?:^|\/)(?:(?:dockerfile|containerfile)(?:\.[^/]+)?|[^/]+\.dockerfile)$/i;

export function isDockerfilePath(relPath: string): boolean {
  return DOCKERFILE.test(relPath.split("\\").join("/"));
}

const AGENT_INSTRUCTION_FILE =
  /(?:^|\/)(?:AGENTS|SKILL|CLAUDE)[\w-]*\.md$|(?:^|\/)\.(?:claude|opencode|codex|cursor|agents)\/.+$|(?:^|\/)(?:\.mcp\.json|mcp\.json|opencode\.jsonc?)$/;

/**
 * Instruction and configuration files that coding agents load and act on.
 * They are Markdown or JSON but they are not documentation.
 */
export function isAgentInstructionFile(relPath: string): boolean {
  return AGENT_INSTRUCTION_FILE.test(relPath.split("\\").join("/"));
}

/**
 * Detectors for credentials in a provider-specific format (fixed prefix and
 * length). Such a value is a live-looking credential wherever it is found.
 * Documented example values are handled separately (`placeholder-value`).
 */
const PROVIDER_CREDENTIAL_RULE =
  /^(?:secret-(?:aws-access-key|github-token|slack-token)|gitleaks-(?:aws-access-token|github-[a-z0-9-]+|slack-[a-z0-9-]+|gitlab-[a-z0-9-]+|stripe-access-token))$/;

export function isProviderCredentialRule(ruleId: string): boolean {
  return PROVIDER_CREDENTIAL_RULE.test(ruleId);
}

/**
 * Secrets whose format says what they are: a PEM private-key block and
 * credentials embedded in a URL. Like provider tokens they keep their
 * confidence in every path context; an obvious placeholder is handled
 * separately (`placeholder-value`).
 */
const FORMAT_CREDENTIAL_RULE =
  /^(?:secret-private-key|secret-url-credentials|gitleaks-private-key)$/;

export function isFormatCredentialRule(ruleId: string): boolean {
  return FORMAT_CREDENTIAL_RULE.test(ruleId);
}

/** What the scan knows about the file a finding is in. */
export interface PathContextFile {
  pathContext?: PathContext;
  /** `header`: decided by a generated-file comment, which lowers nothing. */
  pathContextSource?: PathContextSource;
  /** Inventory kind; `lockfile` and `manifest` are dependency manifests. */
  kind?: string;
  language?: string;
}

/**
 * Why a finding keeps its confidence whatever its path context, or undefined
 * when the path context applies to it.
 */
export function pathContextExemption(
  finding: Pick<Finding, "ruleId" | "category" | "file" | "provenance"> &
    Partial<Pick<Finding, "severity" | "confidence">>,
  file: PathContextFile | undefined,
): string | undefined {
  const rules = (finding.provenance as { rules?: unknown }).rules;
  const ruleIds = [
    finding.ruleId,
    ...(Array.isArray(rules) ? rules.filter((rule): rule is string => typeof rule === "string") : []),
  ];
  if (ruleIds.some((ruleId) => isProviderCredentialRule(ruleId))) return "provider-credential";
  if (ruleIds.some((ruleId) => isFormatCredentialRule(ruleId))) return "format-credential";
  if (finding.severity === "critical" && finding.confidence === "high") {
    return "critical-high-confidence";
  }
  if (isCiFile(finding.file)) return "ci-file";
  if (file?.language === "dockerfile" || isDockerfilePath(finding.file)) return "dockerfile";
  if (finding.category === "sca" || file?.kind === "lockfile" || file?.kind === "manifest") {
    return "dependency-manifest";
  }
  if (isAgentInstructionFile(finding.file)) return "agent-instruction-file";
  return undefined;
}

export interface PathContextOptions {
  /** `--include-tests`: record the context but do not lower any confidence. */
  includeTests?: boolean;
}

/**
 * Record the path context of a finding and lower its confidence: one step for
 * test, docs and example files, to low for vendored and generated paths. A
 * context decided by a header comment is recorded only.
 * `contextOf` returns what the inventory knows about a file; a file the
 * inventory did not read (an external engine reported it) is classified by
 * its path alone.
 */
export function applyPathContext<T extends Finding>(
  finding: T,
  file: PathContextFile | undefined,
  options: PathContextOptions = {},
): T {
  const context = file ? file.pathContext : classifyPath(finding.file);
  if (!context) return finding;
  const tagged: T = { ...finding, pathContext: context };
  if (options.includeTests) return tagged;
  // A header comment is free for whoever wrote the file: record, do not lower.
  if (file?.pathContextSource === "header") return tagged;
  if (pathContextExemption(finding, file) !== undefined) return tagged;
  return lowerConfidence(
    tagged,
    `${ADJUSTMENT_PATH_CONTEXT_PREFIX}${context}`,
    context === "vendored" || context === "generated" ? "low" : "step",
  );
}

export type PathContextCounts = Record<PathContext, number> & { lowered: number };

/**
 * Findings per path context and how many of them had their confidence lowered
 * because of it. Suppressed findings are not counted.
 */
export function countPathContexts(findings: readonly Finding[]): PathContextCounts {
  const counts = { lowered: 0 } as PathContextCounts;
  for (const context of PATH_CONTEXTS) counts[context] = 0;
  for (const finding of findings) {
    if (finding.status === "suppressed") continue;
    if (!finding.pathContext) continue;
    counts[finding.pathContext] += 1;
    if (finding.adjustments?.some((reason) => reason.startsWith(ADJUSTMENT_PATH_CONTEXT_PREFIX))) {
      counts.lowered += 1;
    }
  }
  return counts;
}
